def-hyp(
    __list__(
        Type.annotation(@x, X@Topology.ctxt.X),
        Type.annotation(@y, Y@Topology.ctxt.Y),
        Type.annotation(@x_0, X@Topology.ctxt.X)
    ),
    Topology.mapLimit(x, x_0, f@Topology.ctxt.f, y),
    Logic.forall-typed(
        @V,
        Set(Y@Topology.ctxt.Y),
        Logic.implies(
            Set.mem(V, τ_Y@Topology.ctxt.tauY),
            Logic.and(
                Set.mem(y, V),
                Logic.exists-typed(
                    @U,
                    Set(X@Topology.ctxt.X),
                    Logic.and(
                        Topology.deletedNeighborhood(U, x_0),
                        Set.subset(
                            Set.fun(f@Topology.ctxt.f, U),
                            V
                        )
                    )
                )
            )
        )
    )
)
